// =========================================================
// Filtrar Vendas Faturadas no Mês
// A comissão pertence ao mês de EMISSÃO DA NOTA FISCAL, não ao mês
// da data da venda. Mantém só as vendas com nota emitida no mês
// corrente (referência: $today). Venda sem nota ou sem data de
// emissão é DESCARTADA: sem nota, não houve faturamento.
// =========================================================
const CHAVES_LISTA = ['dados', 'data', 'registros', 'records', 'results', 'rows', 'itens', 'items', 'body'];
function extrairRegistros(entrada) {
  const out = [];
  const visitar = (v) => {
    if (v === null || v === undefined) return;
    if (Array.isArray(v)) { v.forEach(visitar); return; }
    if (typeof v === 'string') {
      const s = v.trim();
      if (s.startsWith('[') || s.startsWith('{')) {
        try { visitar(JSON.parse(s)); } catch (e) {}
      }
      return;
    }
    if (typeof v === 'object') {
      const chave = CHAVES_LISTA.find((k) => Array.isArray(v[k]) || (typeof v[k] === 'string' && String(v[k]).trim().startsWith('[')));
      if (chave) { visitar(v[chave]); return; }
      out.push(v);
    }
  };
  entrada.forEach((it) => visitar(it && it.json !== undefined ? it.json : it));
  return out;
}
function normKey(k) {
  return String(k).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
}
function pega(json, candidatos) {
  const mapa = {};
  Object.keys(json).forEach((k) => { mapa[normKey(k)] = json[k]; });
  for (const c of candidatos) {
    const v = mapa[normKey(c)];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return null;
}

// ---- Campos aceitos (ajuste se o relatório usar outro nome)
// Só datas de emissão da NF: a data da venda NÃO decide o mês da comissão.
const CAMPOS_DATA = ['data_emissao_nota', 'data_emissao_nota_fiscal', 'data_emissao_nf', 'dt_emissao_nf', 'data_emissao', 'dt_emissao', 'emissao', 'data_faturamento'];
const CAMPOS_NOTA = ['numnota', 'numero_nota', 'numero_nota_fiscal', 'nota_fiscal', 'nr_nota'];

// Aceita AAAA-MM-DD (ISO), DD/MM/AAAA e timestamp em milissegundos
function anoMes(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') {
    if (v < 100000000000) return null;
    const d = new Date(v);
    return { ano: d.getUTCFullYear(), mes: d.getUTCMonth() + 1 };
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return { ano: Number(m[1]), mes: Number(m[2]) };
  m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (m) return { ano: Number(m[3]), mes: Number(m[2]) };
  return null;
}

const hoje = String($today).split('-');
const ANO = Number(hoje[0]);
const MES = Number(hoje[1]);

const registros = extrairRegistros(items);
let semNota = 0;
let semData = 0;
const doMes = registros.filter((r) => {
  const nota = pega(r, CAMPOS_NOTA);
  if (nota === null || String(nota).trim() === '0') { semNota += 1; return false; }
  const am = anoMes(pega(r, CAMPOS_DATA));
  if (!am) { semData += 1; return false; }
  return am.ano === ANO && am.mes === MES;
});

console.log('Vendas recebidas: ' + registros.length + ' | faturadas no mês: ' + doMes.length + ' | sem nota (descartadas): ' + semNota + ' | sem data de emissão (descartadas): ' + semData);
return doMes.map((r) => ({ json: r }));

// =========================================================
// Comissão de vendas - Code node (n8n)
// Base de cálculo: valor_total_venda (JÁ LÍQUIDO, desconto abatido)
// Faixa de comissão: percentual de desconto SOBRE O BRUTO
// Sem arredondamento: valores saem com precisão total
// =========================================================

// ---- Ajustes rápidos
const NOME_TABELA = "Tabela de Comissão";

// O campo percentual_desconto da origem vem dividido pelo LÍQUIDO
// (ex.: 130,15 / 70,05 = 185,79%), o que estoura as faixas da tabela.
// Padrão: recalcular sobre o bruto (líquido + desconto).
const RECALCULAR_DESCONTO = true;

// ---- Tabela de comissão: "ate" = limite superior INCLUSIVE do desconto
const FAIXAS = [
  { ate: 0,    perc: 5.00 },
  { ate: 5,    perc: 4.80 },
  { ate: 10,   perc: 4.50 },
  { ate: 12.5, perc: 4.30 },
  { ate: 15,   perc: 4.00 },
  { ate: 17.5, perc: 3.80 },
  { ate: 20,   perc: 3.50 },
  { ate: 22.5, perc: 3.30 },
  { ate: 25,   perc: 3.00 },
  { ate: 27.5, perc: 2.80 },
  { ate: 30,   perc: 2.50 },
  { ate: 32.5, perc: 2.30 },
  { ate: 35,   perc: 2.00 },
  { ate: 37.5, perc: 1.80 },
  { ate: 40,   perc: 1.50 },
  { ate: 42.5, perc: 1.30 },
  { ate: 45,   perc: 1.00 },
  { ate: 47.5, perc: 0.80 },
  { ate: 50,   perc: 0.50 },
  { ate: 55,   perc: 0.30 },
  { ate: Infinity, perc: 0.00 },
];

// ---- Helpers (pt-BR manual, sem Intl: não roda no sandbox do n8n)
const pct1 = (n) => n.toFixed(1).replace(".", ",") + "%";
const pct2 = (n) => n.toFixed(2).replace(".", ",") + "%";

function num(v) {
  if (v === null || v === undefined || v === "") return NaN;
  if (typeof v === "number") return v;
  const s = String(v).trim().replace(/R\$|\s|%/g, "");
  return Number(s.includes(",") ? s.replace(/\./g, "").replace(",", ".") : s);
}

// ---- Desempacota payloads aninhados: 1 item com array dentro vira N itens
const CHAVES_LISTA = ["dados", "data", "registros", "records", "results", "rows", "itens", "items", "body"];
function extrairRegistros(entrada) {
  const out = [];
  const visitar = (v) => {
    if (v === null || v === undefined) return;
    if (Array.isArray(v)) { v.forEach(visitar); return; }
    if (typeof v === "string") {
      const s = v.trim();
      if (s.startsWith("[") || s.startsWith("{")) {
        try { visitar(JSON.parse(s)); } catch (e) {}
      }
      return;
    }
    if (typeof v === "object") {
      const chave = CHAVES_LISTA.find((k) => Array.isArray(v[k]) || (typeof v[k] === "string" && String(v[k]).trim().startsWith("[")));
      if (chave) { visitar(v[chave]); return; }
      out.push(v);
    }
  };
  entrada.forEach((it) => visitar(it && it.json !== undefined ? it.json : it));
  return out;
}

// ---- Leitura de campo tolerante a acento, caixa, underscore e prefixo
function normKey(k) {
  return String(k)
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase().replace(/[^a-z0-9]/g, "");
}
function pega(json, candidatos) {
  const mapa = {};
  Object.keys(json).forEach((k) => { mapa[normKey(k)] = json[k]; });
  for (const c of candidatos) {
    const v = mapa[normKey(c)];
    if (v !== undefined && v !== null && v !== "") return v;
  }
  return null;
}

function faixaDe(pd) {
  for (let i = 0; i < FAIXAS.length; i++) {
    if (pd <= FAIXAS[i].ate) {
      const f = FAIXAS[i];
      let descricao;
      if (i === 0) descricao = "desconto igual a 0%: comissão " + pct1(f.perc);
      else if (f.ate === Infinity) descricao = "desconto acima de " + pct1(FAIXAS[i - 1].ate) + ": comissão " + pct1(f.perc);
      else descricao = "desconto acima de " + pct1(FAIXAS[i - 1].ate) + " até " + pct1(f.ate) + ": comissão " + pct1(f.perc);
      return { perc: f.perc, descricao };
    }
  }
  return { perc: 0, descricao: "faixa não encontrada" };
}

// ---- Processamento venda a venda
const vendas = extrairRegistros(items);

return vendas.map((json) => {
  // ATENÇÃO: "vendedor" (sem "nom") é o CÓDIGO do vendedor, não entra como nome
  const cnpj_origem   = pega(json, ["_cnpjOrigem", "cnpj_origem", "cnpjorigem", "cnpj"]);
  const razao_origem  = pega(json, ["_razaoOrigem", "razao_origem", "razaoorigem", "razao_social", "razao"]);
  const nome_cliente  = pega(json, ["nomcliente", "nome_cliente", "nomecliente", "cliente", "razao_social_cliente"]);
  const nome_vendedor = pega(json, ["nomvendedor", "nome_vendedor", "nomevendedor", "vendedor_nome", "representante"]);
  const numero_venda  = pega(json, ["lancamento", "numero_venda", "num_venda", "nr_venda", "nro_venda", "numvenda", "numero_pedido", "num_pedido", "nr_pedido", "numero_nota", "nota_fiscal", "id_venda"]);

  const liquido  = num(pega(json, ["valor_total_venda", "valor_venda", "valor_liquido", "total_venda"]));
  const desconto = num(pega(json, ["valor_total_desconto", "desconto_total", "valor_desconto", "desconto"]));
  const numero_nota     = pega(json, ["numnota", "numero_nota", "numero_nota_fiscal", "nota_fiscal", "nr_nota"]);
  const data_emissao_nf = pega(json, ["data_emissao_nota", "data_emissao_nota_fiscal", "data_emissao_nf", "data_emissao"]);
  const data_venda      = pega(json, ["data_venda", "data_da_venda", "dt_venda"]);

  const bruto = (!isNaN(liquido) && !isNaN(desconto)) ? liquido + desconto : NaN;

  // percentual sobre o bruto, do jeito que a tabela de comissão espera
  const pdBruto = (!isNaN(bruto) && bruto > 0) ? (desconto / bruto) * 100 : NaN;

  // fallback: converte o percentual da origem (sobre líquido) para base bruto
  // r = desconto/liquido  ->  desconto/bruto = r / (1 + r)
  const pdCampoLiq = num(pega(json, ["percentual_desconto", "perc_desconto", "percentual_desconto_venda"]));
  const pdCampoConvertido = !isNaN(pdCampoLiq) ? (pdCampoLiq / (1 + pdCampoLiq / 100)) : NaN;

  let pdUsado;
  if (RECALCULAR_DESCONTO) pdUsado = !isNaN(pdBruto) ? pdBruto : pdCampoConvertido;
  else pdUsado = !isNaN(pdCampoLiq) ? pdCampoLiq : pdBruto;

  let percentual_comissao = 0;
  let regra_aplicada = "";

  if (isNaN(pdUsado)) {
    regra_aplicada = "percentual de desconto indisponível: comissão 0%";
  } else {
    const pd = pdUsado < 0 ? 0 : pdUsado;
    const f = faixaDe(pd);
    percentual_comissao = f.perc;
    regra_aplicada = f.descricao + (pdUsado < 0 ? " (desconto negativo tratado como 0%)" : "");
  }

  // Comissão SEMPRE sobre o valor líquido da venda, sem abater desconto de novo
  const valor_comissao = isNaN(liquido) ? null : (liquido * percentual_comissao / 100);

  return {
    json: {
      cnpj_origem: cnpj_origem,
      razao_origem: razao_origem,
      nome_cliente: nome_cliente,
      nome_vendedor: nome_vendedor,
      numero_venda: numero_venda,
      numero_nota: numero_nota,
      data_emissao_nf: data_emissao_nf,
      data_venda: data_venda,
      subtotal_venda: (function () {
        const st = num(pega(json, ["subtotal_venda", "subtotal_da_venda", "subtotal", "valor_bruto"]));
        if (!isNaN(st)) return st;
        return isNaN(bruto) ? null : Math.round(bruto * 100) / 100;
      })(),
      valor_total_venda: isNaN(liquido) ? null : liquido,
      valor_total_desconto: isNaN(desconto) ? null : desconto,
      percentual_desconto_usado: isNaN(pdUsado) ? null : pdUsado,
      regra_comissao_aplicada: regra_aplicada,
      tabela_comissao: NOME_TABELA + ": " + pct2(percentual_comissao),
      valor_comissao: valor_comissao,
    },
  };
});

// =========================================================
// Consolidar Comissões
// Entradas:
//   items                               -> cadastro de vendedores ("Buscar Vendedores")
//   $node['Agregar Vendas'].json.vendas -> vendas já calculadas ("Calcular Comissão")
// O cálculo da comissão NÃO muda aqui: este node só agrupa, soma e formata.
// Valores em R$ são arredondados para 2 casas apenas na apresentação.
// =========================================================

const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const hoje = String($today).split('-');
const ANO = Number(hoje[0]);
const MES = Number(hoje[1]);
const DIA = Number(hoje[2]);
const pad = (n) => (n < 10 ? '0' : '') + n;
const MES_REF = MESES[MES - 1] + '/' + ANO;
const DATA_EXEC = pad(DIA) + '/' + pad(MES) + '/' + ANO;

// ---- Formatação pt-BR manual (sem Intl)
const r2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
function brl(n) {
  const v = r2(n);
  const partes = Math.abs(v).toFixed(2).split('.');
  const inteiro = partes[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (v < 0 ? '-' : '') + 'R$ ' + inteiro + ',' + partes[1];
}
function esc(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

// ---- Leitura tolerante (mesma lógica do "Calcular Comissão")
const CHAVES_LISTA = ['dados', 'data', 'registros', 'records', 'results', 'rows', 'itens', 'items', 'body'];
function extrairRegistros(entrada) {
  const out = [];
  const visitar = (v) => {
    if (v === null || v === undefined) return;
    if (Array.isArray(v)) { v.forEach(visitar); return; }
    if (typeof v === 'string') {
      const s = v.trim();
      if (s.startsWith('[') || s.startsWith('{')) {
        try { visitar(JSON.parse(s)); } catch (e) {}
      }
      return;
    }
    if (typeof v === 'object') {
      const chave = CHAVES_LISTA.find((k) => Array.isArray(v[k]) || (typeof v[k] === 'string' && String(v[k]).trim().startsWith('[')));
      if (chave) { visitar(v[chave]); return; }
      out.push(v);
    }
  };
  entrada.forEach((it) => visitar(it && it.json !== undefined ? it.json : it));
  return out;
}
function normKey(k) {
  return String(k).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
}
function pega(json, candidatos) {
  const mapa = {};
  Object.keys(json).forEach((k) => { mapa[normKey(k)] = json[k]; });
  for (const c of candidatos) {
    const v = mapa[normKey(c)];
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return null;
}
// Chave de comparação de nomes: sem acento, minúsculas, espaços únicos
const chaveNome = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();

// ---- 1) Cadastro de vendedores: nome -> e-mail
const CAMPOS_NOME = ['nomvendedor', 'nome_vendedor', 'nomevendedor', 'vendedor_nome', 'nome', 'representante'];
const CAMPOS_EMAIL = ['email', 'e_mail', 'email_vendedor', 'emailvendedor', 'mail', 'endereco_email'];
const cadastro = {};
extrairRegistros(items).forEach((r) => {
  const nome = pega(r, CAMPOS_NOME);
  const email = pega(r, CAMPOS_EMAIL);
  if (!nome || !email || String(email).indexOf('@') < 0) return;
  cadastro[chaveNome(nome)] = String(email).trim();
});

// ---- 2) Agrupa as vendas por vendedor
const agregado = $node['Agregar Vendas'].json || {};
const vendas = Array.isArray(agregado.vendas) ? agregado.vendas : [];
const grupos = {};
vendas.forEach((v) => {
  const nome = v.nome_vendedor ? String(v.nome_vendedor).trim() : 'Sem vendedor';
  const k = chaveNome(nome) || 'sem vendedor';
  if (!grupos[k]) grupos[k] = { chave: k, nome: nome, qtd: 0, vendido: 0, comissao: 0, vendas: [] };
  const g = grupos[k];
  g.qtd += 1;
  g.vendido += r2(v.valor_total_venda);
  g.comissao += r2(v.valor_comissao);
  g.vendas.push(v);
});

// ---- 3) Ranking: do maior para o menor total vendido
const ranking = Object.keys(grupos).map((k) => grupos[k]);
ranking.forEach((g) => { g.vendido = r2(g.vendido); g.comissao = r2(g.comissao); });
ranking.sort((a, b) => (b.vendido - a.vendido) || (b.comissao - a.comissao));
const totalVendido = r2(ranking.reduce((s, g) => s + g.vendido, 0));
const totalComissao = r2(ranking.reduce((s, g) => s + g.comissao, 0));

// ---- 4) Linhas da planilha (mesmas colunas para gerência e vendedores)
// Data AAAA-MM-DD[...] ou DD/MM/AAAA -> DD/MM/AAAA
// Data -> DD/MM/AAAA (padrão brasileiro; a planilha precisa estar com localidade Brasil)
function dataBR(v) {
  if (v === null || v === undefined || v === '') return '';
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[3] + '/' + m[2] + '/' + m[1];
  m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (m) return m[1] + '/' + m[2] + '/' + m[3];
  return s.slice(0, 10);
}
const valorOuVazio = (n) => (n === null || n === undefined || n === '' || isNaN(Number(n)) ? '' : r2(n));
function linha(g, v) {
  // Ordem exata das colunas na planilha
  return {
    'Lançamento': v.numero_venda === null || v.numero_venda === undefined ? '' : String(v.numero_venda),
    'Nº da Nota': v.numero_nota === null || v.numero_nota === undefined ? '' : String(v.numero_nota),
    'Data da Venda': dataBR(v.data_venda),
    'Emissão da NF': dataBR(v.data_emissao_nf),
    'Nome do Cliente': v.nome_cliente || '',
    'Subtotal da Venda': valorOuVazio(v.subtotal_venda),
    'Valor Total da Venda': valorOuVazio(v.valor_total_venda),
    'Valor Total do Desconto': valorOuVazio(v.valor_total_desconto),
    '% do Desconto': valorOuVazio(v.percentual_desconto_usado),
    'Valor da Comissão': valorOuVazio(v.valor_comissao),
    'Regra Aplicada': v.regra_comissao_aplicada || '',
    'Nome do Vendedor': g.nome,
    'Nome da Empresa de Origem': v.razao_origem || '',
  };
}
const linhas = [];
ranking.forEach((g) => {
  g.vendas.sort((a, b) => (Number(b.valor_total_venda) || 0) - (Number(a.valor_total_venda) || 0));
  g.vendas.forEach((v) => linhas.push(linha(g, v)));
});

// ---- 5) Ranking resumido para o e-mail da gerência (o HTML é montado em "Montar E-mail da Gerência")
const rankingResumo = ranking.map((g, i) => ({
  posicao: i + 1, nome: g.nome, qtd: g.qtd, vendido: g.vendido, comissao: g.comissao,
  vendido_fmt: brl(g.vendido), comissao_fmt: brl(g.comissao), tem_email: Boolean(cadastro[g.chave]),
}));

// ---- 6) Vendedores sem e-mail no cadastro (aviso no e-mail da gerência)
const semEmail = ranking.filter((g) => !cadastro[g.chave]);

// ---- 7) Lista do Loop: só quem tem e-mail, SEM as linhas (mantém a expressão do Loop leve)
const vendedores = ranking.filter((g) => cadastro[g.chave]).map((g) => ({
  nome: g.nome,
  email: cadastro[g.chave],
  qtd_vendas: g.qtd,
  total_vendido: g.vendido,
  total_comissao: g.comissao,
  total_vendido_fmt: brl(g.vendido),
  total_comissao_fmt: brl(g.comissao),
  titulo_planilha: 'Comissão ' + MES_REF + ' - ' + g.nome,
}));

console.log('Vendas: ' + vendas.length + ' | vendedores: ' + ranking.length + ' | com e-mail: ' + vendedores.length + ' | sem e-mail: ' + semEmail.length);

return [{
  json: {
    mes_referencia: MES_REF,
    data_execucao: DATA_EXEC,
    qtd_vendas: vendas.length,
    qtd_vendedores: ranking.length,
    total_vendido: totalVendido,
    total_comissao: totalComissao,
    total_vendido_fmt: brl(totalVendido),
    total_comissao_fmt: brl(totalComissao),
    titulo_planilha_geral: 'Comissões ' + MES_REF + ' - Todos os vendedores',
    ranking_resumo: rankingResumo,
    sem_email: semEmail.map((g) => g.nome),
    vendedores: vendedores,
    linhas: linhas,
  },
}];

// Uma linha da planilha por item, com as colunas na ordem exata abaixo.
// O "Gravar Planilha Geral" ordena os cabeçalhos em ordem alfabética; o prefixo
// invisível (zero-width space) em quantidade crescente força esta ordem sem
// mudar o texto visível do cabeçalho.
const COLUNAS = [
  'Lançamento',
  'Nº da Nota',
  'Data da Venda',
  'Emissão da NF',
  'Nome do Cliente',
  'Subtotal da Venda',
  'Valor Total do Desconto',
  'Valor Total da Venda',
  '% do Desconto',
  'Valor da Comissão',
  'Regra Aplicada',
  'Nome do Vendedor',
  'Nome da Empresa de Origem',
];
const ordenar = (l) => {
  const o = {};
  COLUNAS.forEach((c, i) => { o['\u200B'.repeat(i) + c] = l[c] === undefined || l[c] === null ? '' : l[c]; });
  return o;
};

const linhas = $node['Consolidar Comissões'].json.linhas || [];
if (linhas.length === 0) return [{ json: ordenar({ 'Nome do Vendedor': 'Nenhuma venda encontrada no período' }) }];
return linhas.map((l) => ({ json: ordenar(l) }));

// Só as vendas do vendedor da iteração atual do Loop, uma linha por item,
// com as colunas na ordem exata abaixo (mesma lógica da planilha geral).
const COLUNAS = [
  'Lançamento',
  'Nº da Nota',
  'Data da Venda',
  'Emissão da NF',
  'Nome do Cliente',
  'Subtotal da Venda',
  'Valor Total do Desconto',
  'Valor Total da Venda',
  '% do Desconto',
  'Valor da Comissão',
  'Regra Aplicada',
  'Nome do Vendedor',
  'Nome da Empresa de Origem',
];
const ordenar = (l) => {
  const o = {};
  COLUNAS.forEach((c, i) => { o['\u200B'.repeat(i) + c] = l[c] === undefined || l[c] === null ? '' : l[c]; });
  return o;
};

const vendedor = $node['Um Vendedor por Vez'].json;
const linhas = ($node['Consolidar Comissões'].json.linhas || []).filter((l) => l['Nome do Vendedor'] === vendedor.nome);
return linhas.map((l) => ({ json: ordenar(l) }));

// ============================================================
// CONFIG - único bloco que deveria precisar de ajuste
// ============================================================
const CONFIG = {
  nomeEmpresa: "NOME DA EMPRESA",
  titulo: "Comissões do mês por vendedor",
  assunto: "Comissões de {mes} - ranking de vendedores",
  rodape: "Mensagem automática do sistema comercial NOME DA EMPRESA."
};

// ============================================================
// PADRÃO DE E-MAIL WAIPE - copie este bloco para o node `code` que monta o e-mail.
// Desenho de referência: o consolidado do gestor do Guardião da Amostra Padrão (claro, com modo escuro automático).
// Marca "waipe" e empresa no topo, cartão branco com faixa escura, título com eyebrow dourado, indicadores
// em verde-oliva, tabelas claras e rodapé Londrisoft. Todo e-mail de agente do Waipe usa este kit.
// As funções devolvem linhas de tabela (<tr>) para dentro do cartão, exceto wpBadge/wpBarra/wpSeta, que devolvem
// HTML para colocar dentro de uma célula. wpPagina devolve o documento HTML completo.
// Compatível com o sandbox do Waipe Flow (sem toLocaleString, sem Intl).
// ============================================================
const WP_F = "font-family:Arial,Helvetica,sans-serif;";

function wpEsc(t) {
  if (t === null || t === undefined) return "";
  return String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/'/g, "&#39;");
}
function wpNum(n) { return String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, "."); }
function wpMoeda(v) {
  const n = Math.round((Number(v) || 0) * 100) / 100;
  const p = Math.abs(n).toFixed(2).split(".");
  return (n < 0 ? "-R$ " : "R$ ") + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "," + p[1];
}

// Estilos de destaque (badge, KPI e aviso): fundo, texto e borda. As cores do modo escuro ficam no <style> de wpPagina.
const WP_ESTILOS = {
  neutro: { bg: "#F9FAFB", cor: "#303030", borda: "#E5E7EB" },
  medio: { bg: "#F1F2EC", cor: "#5A6344", borda: "#E3E6D8" },
  forte: { bg: "#5A6344", cor: "#FFFFFF", borda: "#5A6344" },
  alerta: { bg: "#FEF3F2", cor: "#B42318", borda: "#FAD7D3" },
  ok: { bg: "#EEF8F1", cor: "#1E7A45", borda: "#CDEBD7" }
};

// Documento completo: marca e empresa, cartão (eyebrow, título, saudação, destaque), miolo (linhas) e rodapé.
// o: { preheader, empresa, rotuloDireita, eyebrow, titulo, heroEyebrow, heroValor, heroTam, heroSub, heroBarra,
//      heroNota, saudacao, subSaudacao, miolo, rodape: [linhas] }
// eyebrow/titulo são opcionais: sem eles, heroEyebrow vira o eyebrow do cartão.
function wpPagina(o) {
  const eyebrow = o.eyebrow || o.heroEyebrow || "";
  let h = "";
  h += "<!DOCTYPE html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>";
  h += "<meta name='color-scheme' content='light dark'><meta name='supported-color-schemes' content='light dark'>";
  h += "<title>" + wpEsc(o.titulo || eyebrow || o.empresa || "Waipe") + "</title>";
  h += "<style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;}a{color:#303030;}";
  h += "@media only screen and (max-width:620px){.wp-wrap{width:100%!important;max-width:100%!important;}.wp-pad{padding-left:16px!important;padding-right:16px!important;}.wp-kpi{display:block!important;width:100%!important;padding:0 0 8px 0!important;}.wp-hide{display:none!important;}.wp-h1{font-size:24px!important;line-height:30px!important;}.wp-hero{font-size:40px!important;line-height:44px!important;}}";
  h += "@media (prefers-color-scheme: dark){.wp-bg{background:#16181D!important;}.wp-card{background:#1F2229!important;border-color:#323743!important;}.wp-soft{background:#272B33!important;}.wp-t{color:#F3F4F6!important;}.wp-m{color:#A8AEBB!important;}.wp-bd{border-color:#323743!important;}.wp-eb{color:#D4B25A!important;}";
  h += "td[bgcolor='#303030']{background:#E5E7EB!important;}td[bgcolor='#303030'] a{color:#1F2229!important;}";
  h += "td[bgcolor='#F9FAFB']{background:#272B33!important;}td[bgcolor='#F1F2EC']{background:#2A2E24!important;}td[bgcolor='#E3E6D8']{background:#3A4030!important;}";
  h += "td[bgcolor='#FEF3F2']{background:#3A2422!important;}td[bgcolor='#EEF8F1']{background:#1F3A2C!important;}td[bgcolor='#F3F4F6']{background:#272B33!important;}";
  h += ".wp-c-medio{color:#C9CFB4!important;}.wp-c-neutro{color:#F3F4F6!important;}.wp-c-alerta{color:#FCA5A5!important;}.wp-c-ok{color:#86EFAC!important;}}";
  h += "</style></head>";
  h += "<body class='wp-bg' style='margin:0;padding:0;background:#F3F4F6;'>";
  h += "<span style='display:none;font-size:1px;color:#F3F4F6;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;'>" + wpEsc(o.preheader || "") + "</span>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' bgcolor='#F3F4F6' class='wp-bg' style='background:#F3F4F6;'><tr><td align='center' style='padding:32px 12px;'>";
  h += "<!--[if mso]><table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0'><tr><td><![endif]-->";
  h += "<table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0' class='wp-wrap' style='width:600px;max-width:600px;'>";
  // Marca
  h += "<tr><td class='wp-pad' style='padding:0 8px 16px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  h += "<td class='wp-t' style='" + WP_F + "font-size:22px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:28px;'>waipe</td>";
  h += "<td align='right' class='wp-m' style='" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(o.empresa || "") + (o.rotuloDireita ? "<br>" + o.rotuloDireita : "") + "</td>";
  h += "</tr></table></td></tr>";
  // Cartão
  h += "<tr><td bgcolor='#FEFEFE' class='wp-card' style='background:#FEFEFE;border:1px solid #E5E7EB;border-radius:12px;overflow:hidden;'>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>";
  h += "<tr><td height='4' bgcolor='#303030' style='height:4px;font-size:0;line-height:0;background:#303030;border-radius:12px 12px 0 0;'>&nbsp;</td></tr>";
  if (eyebrow || o.titulo || o.saudacao) {
    h += "<tr><td class='wp-pad' style='padding:32px 32px 8px 32px;'>";
    if (eyebrow) h += "<p class='wp-eb' style='margin:0 0 8px 0;" + WP_F + "font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#8E6A1F;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(eyebrow) + "</p>";
    if (o.titulo) h += "<h1 class='wp-h1 wp-t' style='margin:0 0 12px 0;" + WP_F + "font-size:28px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:34px;'>" + wpEsc(o.titulo) + "</h1>";
    if (o.saudacao) h += "<p class='wp-t' style='margin:0;" + WP_F + "font-size:15px;color:#303030;mso-line-height-rule:exactly;line-height:23px;'>" + o.saudacao + "</p>";
    if (o.subSaudacao) h += "<p class='wp-m' style='margin:6px 0 0 0;" + WP_F + "font-size:15px;color:#5B6170;mso-line-height-rule:exactly;line-height:23px;'>" + o.subSaudacao + "</p>";
    h += "</td></tr>";
  }
  if (o.heroValor !== undefined && o.heroValor !== null) {
    const tam = Math.min(o.heroTam || 44, 48);
    h += "<tr><td class='wp-pad' style='padding:20px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='#F1F2EC' style='background:#F1F2EC;border-radius:8px;padding:20px;'>";
    if (o.heroEyebrow && o.eyebrow && o.eyebrow !== o.heroEyebrow) h += "<p class='wp-c-medio' style='margin:0 0 6px 0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#5A6344;mso-line-height-rule:exactly;line-height:15px;'>" + wpEsc(o.heroEyebrow) + "</p>";
    h += "<p class='wp-hero wp-c-medio' style='margin:0;" + WP_F + "font-size:" + tam + "px;font-weight:bold;color:#5A6344;letter-spacing:-1px;mso-line-height-rule:exactly;line-height:" + (tam + 4) + "px;'>" + wpEsc(o.heroValor) + "</p>";
    if (o.heroSub) h += "<p class='wp-c-medio' style='margin:6px 0 0 0;" + WP_F + "font-size:14px;color:#5A6344;mso-line-height-rule:exactly;line-height:20px;'>" + o.heroSub + "</p>";
    if (o.heroBarra !== undefined && o.heroBarra !== null) {
      const w = Math.max(0, Math.min(100, Math.round(o.heroBarra)));
      h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='margin-top:14px;'><tr><td bgcolor='#E3E6D8' style='background:#E3E6D8;border-radius:5px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>" +
        "<td width='" + w + "%' height='10' bgcolor='#5A6344' style='height:10px;background:#5A6344;border-radius:5px;font-size:0;line-height:0;'>&nbsp;</td>" +
        (w < 100 ? "<td height='10' style='height:10px;font-size:0;line-height:0;'>&nbsp;</td>" : "") + "</tr></table></td></tr></table>";
    }
    if (o.heroNota) h += "<p class='wp-c-medio' style='margin:10px 0 0 0;" + WP_F + "font-size:12px;color:#5A6344;mso-line-height-rule:exactly;line-height:18px;'>" + o.heroNota + "</p>";
    h += "</td></tr></table></td></tr>";
  }
  h += o.miolo || "";
  h += "<tr><td style='height:24px;font-size:0;line-height:0;'>&nbsp;</td></tr>";
  h += "</table></td></tr>";
  // Rodapé
  const linhasRodape = o.rodape || [];
  h += "<tr><td class='wp-pad' align='center' style='padding:24px 24px 0 24px;'>";
  for (let i = 0; i < linhasRodape.length; i++) {
    h += "<p class='wp-m' style='margin:" + (i > 0 ? "6px" : "0") + " 0 0 0;" + WP_F + "font-size:12px;color:" + (i === linhasRodape.length - 1 ? "#8A90A0" : "#6B7280") + ";mso-line-height-rule:exactly;line-height:18px;'>" + linhasRodape[i] + "</p>";
  }
  h += "</td></tr></table>";
  h += "<!--[if mso]></td></tr></table><![endif]-->";
  h += "</td></tr></table></body></html>";
  return h;
}

// Parágrafo livre (HTML já escapado pelo chamador)
function wpTexto(html) {
  return "<tr><td class='wp-pad' style='padding:8px 32px;'><p class='wp-m' style='margin:0;" + WP_F + "font-size:15px;color:#5B6170;mso-line-height-rule:exactly;line-height:23px;'>" + html + "</p></td></tr>";
}

// Título de seção com subtítulo
function wpSecao(titulo, sub) {
  return "<tr><td class='wp-pad' style='padding:24px 32px 12px 32px;'>" +
    "<p class='wp-t' style='margin:0;" + WP_F + "font-size:16px;font-weight:bold;color:#303030;mso-line-height-rule:exactly;line-height:22px;'>" + wpEsc(titulo) + "</p>" +
    (sub ? "<p class='wp-m' style='margin:4px 0 0 0;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:18px;'>" + sub + "</p>" : "") + "</td></tr>";
}

// Cartões de indicador lado a lado. lista: [{rotulo, valor, estilo, sub}], titulo (opcional) vira um rótulo pequeno acima.
// Sem estilo, o primeiro é "medio" (verde-oliva) e os outros "neutro", como no Guardião.
function wpKpis(lista, titulo) {
  const n = lista.length;
  const larg = (100 / n).toFixed(2);
  let h = "<tr><td class='wp-pad' style='padding:20px 32px 8px 32px;'>";
  if (titulo) h += "<p class='wp-m' style='margin:0 0 8px 0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;mso-line-height-rule:exactly;line-height:15px;'>" + wpEsc(titulo) + "</p>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  // Valor longo (ex.: R$ 99.716,16) com 3 ou mais cartões lado a lado: fonte menor para caber numa linha.
  const maiorValor = lista.reduce(function (m, k) { return Math.max(m, String(k.valor === undefined ? "" : k.valor).length); }, 0);
  const tam = n >= 3 && maiorValor > 9 ? 20 : n >= 2 && maiorValor > 14 ? 20 : 26;
  for (let i = 0; i < n; i++) {
    const k = lista[i];
    const nome = WP_ESTILOS[k.estilo] ? k.estilo : (i === 0 ? "medio" : "neutro");
    const e = nome === "forte" ? WP_ESTILOS.medio : WP_ESTILOS[nome];
    const cls = nome === "forte" ? "medio" : nome;
    const pad = n === 1 ? "" : (i === 0 ? "padding-right:6px;" : (i === n - 1 ? "padding-left:6px;" : "padding:0 3px;"));
    h += "<td class='wp-kpi' width='" + larg + "%' valign='top' style='width:" + larg + "%;" + pad + "'>" +
      "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border-radius:8px;padding:16px;'>" +
      "<p class='wp-c-" + cls + "' style='margin:0;" + WP_F + "font-size:" + tam + "px;font-weight:bold;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:" + (tam + 6) + "px;white-space:nowrap;'>" + wpEsc(k.valor) + "</p>" +
      "<p class='wp-c-" + cls + "' style='margin:4px 0 0 0;" + WP_F + "font-size:13px;color:" + (nome === "neutro" ? "#5B6170" : e.cor) + ";mso-line-height-rule:exactly;line-height:18px;'>" + wpEsc(k.rotulo) + "</p>" +
      (k.sub ? "<p class='wp-m' style='margin:2px 0 0 0;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(k.sub) + "</p>" : "") +
      "</td></tr></table></td>";
  }
  return h + "</tr></table></td></tr>";
}

// Tabela. colunas: [{t, a: "left"|"right"|"center", w, oculta}], linhas: [[html da célula, ...], ...]
// oculta = some em tela pequena. nota (opcional): texto abaixo da tabela.
function wpTabela(colunas, linhas, nota) {
  let h = "<tr><td class='wp-pad' style='padding:4px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' class='wp-bd' style='border:1px solid #E5E7EB;border-radius:8px;border-collapse:separate;'><tr>";
  for (let c = 0; c < colunas.length; c++) {
    const col = colunas[c];
    const canto = c === 0 ? "border-radius:8px 0 0 0;" : (c === colunas.length - 1 ? "border-radius:0 8px 0 0;" : "");
    h += "<td bgcolor='#F9FAFB' align='" + (col.a || "left") + "'" + (col.w ? " width='" + col.w + "'" : "") + " class='wp-soft wp-m" + (col.oculta ? " wp-hide" : "") + "'" +
      " style='background:#F9FAFB;padding:10px 12px;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;mso-line-height-rule:exactly;line-height:15px;" + canto + "'>" + wpEsc(col.t) + "</td>";
  }
  h += "</tr>";
  if (linhas.length === 0) {
    h += "<tr><td colspan='" + colunas.length + "' class='wp-bd wp-m' style='border-top:1px solid #F3F4F6;padding:14px 12px;" + WP_F + "font-size:13px;color:#6B7280;'>Nada para mostrar.</td></tr>";
  }
  for (let i = 0; i < linhas.length; i++) {
    h += "<tr>";
    for (let c = 0; c < colunas.length; c++) {
      const col = colunas[c];
      h += "<td" + (col.a ? " align='" + col.a + "'" : "") + " valign='middle' class='wp-bd wp-t" + (col.oculta ? " wp-hide" : "") + "'" +
        " style='border-top:1px solid #F3F4F6;padding:10px 12px;" + WP_F + "font-size:13px;color:#303030;mso-line-height-rule:exactly;line-height:18px;'>" + (linhas[i][c] === undefined ? "" : linhas[i][c]) + "</td>";
    }
    h += "</tr>";
  }
  h += "</table>" + (nota ? "<p class='wp-m' style='margin:8px 2px 0 2px;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:17px;'>" + nota + "</p>" : "") + "</td></tr>";
  return h;
}

// Pílula de destaque (para dentro de uma célula). a: "left" | "right". Texto curto (até 3 caracteres) vira círculo,
// como a posição do ranking do Guardião.
function wpBadge(texto, estilo, a) {
  const nome = WP_ESTILOS[estilo] ? estilo : "neutro";
  const e = nome === "neutro" ? { bg: "#F3F4F6", cor: "#5B6170" } : WP_ESTILOS[nome];
  const t = String(texto === null || texto === undefined ? "" : texto);
  const alinhar = a === "right" ? " align='right'" : "";
  if (t.length <= 3) {
    return "<table role='presentation' cellpadding='0' cellspacing='0' border='0'" + alinhar + "><tr><td width='24' height='24' align='center' valign='middle' bgcolor='" + e.bg + "' style='width:24px;height:24px;background:" + e.bg + ";border-radius:12px;" + WP_F + "font-size:12px;font-weight:bold;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:24px;'>" + wpEsc(t) + "</td></tr></table>";
  }
  return "<table role='presentation' cellpadding='0' cellspacing='0' border='0'" + alinhar + "><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border-radius:20px;padding:3px 10px;" + WP_F + "font-size:11px;font-weight:bold;color:" + e.cor + ";white-space:nowrap;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(t) + "</td></tr></table>";
}

// Barra proporcional (para dentro de uma célula). pct 0-100; forte = verde-oliva cheio, senão oliva claro
function wpBarra(pct, forte) {
  const w = Math.max(4, Math.min(100, Math.round(pct)));
  const cor = forte ? "#5A6344" : "#BFC4AC";
  return "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='margin-top:6px;'><tr>" +
    "<td width='" + w + "%' height='6' bgcolor='" + cor + "' style='height:6px;background:" + cor + ";border-radius:3px;font-size:0;line-height:0;'>&nbsp;</td>" +
    (w < 100 ? "<td width='" + (100 - w) + "%' height='6' style='height:6px;font-size:0;line-height:0;'>&nbsp;</td>" : "") + "</tr></table>";
}

// Botão quadrado com seta (para dentro de uma célula): abre a planilha ou lista da linha
function wpSeta(url, titulo) {
  return "<table role='presentation' cellpadding='0' cellspacing='0' border='0' align='right'><tr><td width='32' height='32' align='center' valign='middle' bgcolor='#303030' style='width:32px;height:32px;background:#303030;border-radius:8px;'>" +
    "<a href='" + wpEsc(url) + "' target='_blank' title='" + wpEsc(titulo) + "' aria-label='" + wpEsc(titulo) + "' style='display:block;width:32px;" + WP_F + "font-size:18px;font-weight:bold;color:#FFFFFF;text-decoration:none;mso-line-height-rule:exactly;line-height:32px;border-radius:8px;'>&rarr;</a></td></tr></table>";
}

// Botão de chamada (linha própria)
function wpBotao(url, rotulo) {
  return "<tr><td class='wp-pad' align='left' style='padding:16px 32px 8px 32px;'><table role='presentation' cellpadding='0' cellspacing='0' border='0'><tr><td align='center' bgcolor='#303030' style='background:#303030;border-radius:8px;'>" +
    "<a href='" + wpEsc(url) + "' target='_blank' style='display:block;padding:12px 24px;" + WP_F + "font-size:14px;font-weight:bold;color:#FFFFFF;text-decoration:none;mso-line-height-rule:exactly;line-height:20px;border-radius:8px;'>" + wpEsc(rotulo) + "</a></td></tr></table></td></tr>";
}

// Caixa de aviso (linha própria): titulo + corpo em HTML
function wpAviso(titulo, corpoHtml, estilo) {
  const nome = WP_ESTILOS[estilo] ? estilo : "medio";
  const e = nome === "forte" ? WP_ESTILOS.medio : WP_ESTILOS[nome];
  const cls = nome === "forte" ? "medio" : nome;
  return "<tr><td class='wp-pad' style='padding:16px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border:1px solid " + e.borda + ";border-radius:8px;padding:16px 18px;'>" +
    "<p class='wp-c-" + cls + "' style='margin:0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(titulo) + "</p>" +
    "<p class='wp-t' style='margin:8px 0 0 0;" + WP_F + "font-size:13px;color:#303030;mso-line-height-rule:exactly;line-height:20px;'>" + corpoHtml + "</p></td></tr></table></td></tr>";
}
// ============================================================
// FIM DO PADRÃO DE E-MAIL WAIPE
// ============================================================

const c = $node["Consolidar Comissões"].json;
const urlPlanilha = String($node["Criar Planilha Geral"].json.spreadsheetUrl || "");
const ranking = Array.isArray(c.ranking_resumo) ? c.ranking_resumo : [];
const maior = ranking.length > 0 ? ranking[0].vendido : 0;
const linhas = ranking.map(function (g, i) {
  return [
    wpBadge(String(g.posicao), i < 3 ? "forte" : "neutro"),
    "<b>" + wpEsc(g.nome) + "</b>" + wpBarra(maior > 0 ? g.vendido / maior * 100 : 0, i < 3),
    wpEsc(g.vendido_fmt),
    "<b>" + wpEsc(g.comissao_fmt) + "</b>"
  ];
});
if (ranking.length > 0) linhas.push(["", "<b>Total geral</b>", "<b>" + wpEsc(c.total_vendido_fmt) + "</b>", "<b>" + wpEsc(c.total_comissao_fmt) + "</b>"]);
const semEmail = Array.isArray(c.sem_email) ? c.sem_email : [];
const aviso = semEmail.length > 0
  ? wpAviso("Vendedores sem e-mail no cadastro", wpEsc(semEmail.length + " vendedor(es) não receberam o relatório individual: " + semEmail.join(", ") + "."), "alerta")
  : "";

const miolo =
  wpKpis([
    { rotulo: "Total vendido", valor: c.total_vendido_fmt },
    { rotulo: "Vendas no mês", valor: wpNum(c.qtd_vendas) },
    { rotulo: "Vendedores", valor: wpNum(c.qtd_vendedores) }
  ]) +
  wpSecao("Ranking de vendedores", "Do maior para o menor volume vendido no mês.") +
  wpTabela([{ t: "#", w: "44" }, { t: "Vendedor" }, { t: "Vendido", a: "right", oculta: true }, { t: "Comissão", a: "right", w: "110" }], linhas) +
  aviso +
  (urlPlanilha ? wpBotao(urlPlanilha, "Abrir planilha com todas as vendas") : "");

const html = wpPagina({
  titulo: CONFIG.titulo,
  eyebrow: "Comissão mensal",
  preheader: c.total_comissao_fmt + " em comissões de " + c.mes_referencia + ". Veja o ranking de vendedores.",
  empresa: CONFIG.nomeEmpresa,
  rotuloDireita: "Mês de referência &middot; " + wpEsc(c.mes_referencia),
  heroEyebrow: "Comissões do mês",
  heroValor: c.total_comissao_fmt,
  heroTam: 40,
  heroSub: "em comissões sobre as vendas com nota fiscal emitida em " + wpEsc(c.mes_referencia),
  saudacao: "Olá!",
  subSaudacao: "Segue o fechamento de comissões do mês: cada venda com nota fiscal emitida no mês recebeu a comissão da tabela de faixas por desconto.",
  miolo: miolo,
  rodape: [wpEsc(CONFIG.rodape), "Processado em " + wpEsc(c.data_execucao), "Londrisoft &mdash; Londrina, PR"]
});
return [{ json: { assunto: CONFIG.assunto.replace("{mes}", c.mes_referencia), corpo_html: html } }];

// ============================================================
// CONFIG - único bloco que deveria precisar de ajuste
// ============================================================
const CONFIG = {
  nomeEmpresa: "NOME DA EMPRESA",
  assunto: "Sua comissão de {mes}",
  rodape: "Mensagem automática do sistema comercial NOME DA EMPRESA."
};

// ============================================================
// PADRÃO DE E-MAIL WAIPE - copie este bloco para o node `code` que monta o e-mail.
// Desenho de referência: o consolidado do gestor do Guardião da Amostra Padrão (claro, com modo escuro automático).
// Marca "waipe" e empresa no topo, cartão branco com faixa escura, título com eyebrow dourado, indicadores
// em verde-oliva, tabelas claras e rodapé Londrisoft. Todo e-mail de agente do Waipe usa este kit.
// As funções devolvem linhas de tabela (<tr>) para dentro do cartão, exceto wpBadge/wpBarra/wpSeta, que devolvem
// HTML para colocar dentro de uma célula. wpPagina devolve o documento HTML completo.
// Compatível com o sandbox do Waipe Flow (sem toLocaleString, sem Intl).
// ============================================================
const WP_F = "font-family:Arial,Helvetica,sans-serif;";

function wpEsc(t) {
  if (t === null || t === undefined) return "";
  return String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/'/g, "&#39;");
}
function wpNum(n) { return String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, "."); }
function wpMoeda(v) {
  const n = Math.round((Number(v) || 0) * 100) / 100;
  const p = Math.abs(n).toFixed(2).split(".");
  return (n < 0 ? "-R$ " : "R$ ") + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "," + p[1];
}

// Estilos de destaque (badge, KPI e aviso): fundo, texto e borda. As cores do modo escuro ficam no <style> de wpPagina.
const WP_ESTILOS = {
  neutro: { bg: "#F9FAFB", cor: "#303030", borda: "#E5E7EB" },
  medio: { bg: "#F1F2EC", cor: "#5A6344", borda: "#E3E6D8" },
  forte: { bg: "#5A6344", cor: "#FFFFFF", borda: "#5A6344" },
  alerta: { bg: "#FEF3F2", cor: "#B42318", borda: "#FAD7D3" },
  ok: { bg: "#EEF8F1", cor: "#1E7A45", borda: "#CDEBD7" }
};

// Documento completo: marca e empresa, cartão (eyebrow, título, saudação, destaque), miolo (linhas) e rodapé.
// o: { preheader, empresa, rotuloDireita, eyebrow, titulo, heroEyebrow, heroValor, heroTam, heroSub, heroBarra,
//      heroNota, saudacao, subSaudacao, miolo, rodape: [linhas] }
// eyebrow/titulo são opcionais: sem eles, heroEyebrow vira o eyebrow do cartão.
function wpPagina(o) {
  const eyebrow = o.eyebrow || o.heroEyebrow || "";
  let h = "";
  h += "<!DOCTYPE html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>";
  h += "<meta name='color-scheme' content='light dark'><meta name='supported-color-schemes' content='light dark'>";
  h += "<title>" + wpEsc(o.titulo || eyebrow || o.empresa || "Waipe") + "</title>";
  h += "<style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;}a{color:#303030;}";
  h += "@media only screen and (max-width:620px){.wp-wrap{width:100%!important;max-width:100%!important;}.wp-pad{padding-left:16px!important;padding-right:16px!important;}.wp-kpi{display:block!important;width:100%!important;padding:0 0 8px 0!important;}.wp-hide{display:none!important;}.wp-h1{font-size:24px!important;line-height:30px!important;}.wp-hero{font-size:40px!important;line-height:44px!important;}}";
  h += "@media (prefers-color-scheme: dark){.wp-bg{background:#16181D!important;}.wp-card{background:#1F2229!important;border-color:#323743!important;}.wp-soft{background:#272B33!important;}.wp-t{color:#F3F4F6!important;}.wp-m{color:#A8AEBB!important;}.wp-bd{border-color:#323743!important;}.wp-eb{color:#D4B25A!important;}";
  h += "td[bgcolor='#303030']{background:#E5E7EB!important;}td[bgcolor='#303030'] a{color:#1F2229!important;}";
  h += "td[bgcolor='#F9FAFB']{background:#272B33!important;}td[bgcolor='#F1F2EC']{background:#2A2E24!important;}td[bgcolor='#E3E6D8']{background:#3A4030!important;}";
  h += "td[bgcolor='#FEF3F2']{background:#3A2422!important;}td[bgcolor='#EEF8F1']{background:#1F3A2C!important;}td[bgcolor='#F3F4F6']{background:#272B33!important;}";
  h += ".wp-c-medio{color:#C9CFB4!important;}.wp-c-neutro{color:#F3F4F6!important;}.wp-c-alerta{color:#FCA5A5!important;}.wp-c-ok{color:#86EFAC!important;}}";
  h += "</style></head>";
  h += "<body class='wp-bg' style='margin:0;padding:0;background:#F3F4F6;'>";
  h += "<span style='display:none;font-size:1px;color:#F3F4F6;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;'>" + wpEsc(o.preheader || "") + "</span>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' bgcolor='#F3F4F6' class='wp-bg' style='background:#F3F4F6;'><tr><td align='center' style='padding:32px 12px;'>";
  h += "<!--[if mso]><table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0'><tr><td><![endif]-->";
  h += "<table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0' class='wp-wrap' style='width:600px;max-width:600px;'>";
  // Marca
  h += "<tr><td class='wp-pad' style='padding:0 8px 16px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  h += "<td class='wp-t' style='" + WP_F + "font-size:22px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:28px;'>waipe</td>";
  h += "<td align='right' class='wp-m' style='" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(o.empresa || "") + (o.rotuloDireita ? "<br>" + o.rotuloDireita : "") + "</td>";
  h += "</tr></table></td></tr>";
  // Cartão
  h += "<tr><td bgcolor='#FEFEFE' class='wp-card' style='background:#FEFEFE;border:1px solid #E5E7EB;border-radius:12px;overflow:hidden;'>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>";
  h += "<tr><td height='4' bgcolor='#303030' style='height:4px;font-size:0;line-height:0;background:#303030;border-radius:12px 12px 0 0;'>&nbsp;</td></tr>";
  if (eyebrow || o.titulo || o.saudacao) {
    h += "<tr><td class='wp-pad' style='padding:32px 32px 8px 32px;'>";
    if (eyebrow) h += "<p class='wp-eb' style='margin:0 0 8px 0;" + WP_F + "font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#8E6A1F;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(eyebrow) + "</p>";
    if (o.titulo) h += "<h1 class='wp-h1 wp-t' style='margin:0 0 12px 0;" + WP_F + "font-size:28px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:34px;'>" + wpEsc(o.titulo) + "</h1>";
    if (o.saudacao) h += "<p class='wp-t' style='margin:0;" + WP_F + "font-size:15px;color:#303030;mso-line-height-rule:exactly;line-height:23px;'>" + o.saudacao + "</p>";
    if (o.subSaudacao) h += "<p class='wp-m' style='margin:6px 0 0 0;" + WP_F + "font-size:15px;color:#5B6170;mso-line-height-rule:exactly;line-height:23px;'>" + o.subSaudacao + "</p>";
    h += "</td></tr>";
  }
  if (o.heroValor !== undefined && o.heroValor !== null) {
    const tam = Math.min(o.heroTam || 44, 48);
    h += "<tr><td class='wp-pad' style='padding:20px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='#F1F2EC' style='background:#F1F2EC;border-radius:8px;padding:20px;'>";
    if (o.heroEyebrow && o.eyebrow && o.eyebrow !== o.heroEyebrow) h += "<p class='wp-c-medio' style='margin:0 0 6px 0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#5A6344;mso-line-height-rule:exactly;line-height:15px;'>" + wpEsc(o.heroEyebrow) + "</p>";
    h += "<p class='wp-hero wp-c-medio' style='margin:0;" + WP_F + "font-size:" + tam + "px;font-weight:bold;color:#5A6344;letter-spacing:-1px;mso-line-height-rule:exactly;line-height:" + (tam + 4) + "px;'>" + wpEsc(o.heroValor) + "</p>";
    if (o.heroSub) h += "<p class='wp-c-medio' style='margin:6px 0 0 0;" + WP_F + "font-size:14px;color:#5A6344;mso-line-height-rule:exactly;line-height:20px;'>" + o.heroSub + "</p>";
    if (o.heroBarra !== undefined && o.heroBarra !== null) {
      const w = Math.max(0, Math.min(100, Math.round(o.heroBarra)));
      h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='margin-top:14px;'><tr><td bgcolor='#E3E6D8' style='background:#E3E6D8;border-radius:5px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>" +
        "<td width='" + w + "%' height='10' bgcolor='#5A6344' style='height:10px;background:#5A6344;border-radius:5px;font-size:0;line-height:0;'>&nbsp;</td>" +
        (w < 100 ? "<td height='10' style='height:10px;font-size:0;line-height:0;'>&nbsp;</td>" : "") + "</tr></table></td></tr></table>";
    }
    if (o.heroNota) h += "<p class='wp-c-medio' style='margin:10px 0 0 0;" + WP_F + "font-size:12px;color:#5A6344;mso-line-height-rule:exactly;line-height:18px;'>" + o.heroNota + "</p>";
    h += "</td></tr></table></td></tr>";
  }
  h += o.miolo || "";
  h += "<tr><td style='height:24px;font-size:0;line-height:0;'>&nbsp;</td></tr>";
  h += "</table></td></tr>";
  // Rodapé
  const linhasRodape = o.rodape || [];
  h += "<tr><td class='wp-pad' align='center' style='padding:24px 24px 0 24px;'>";
  for (let i = 0; i < linhasRodape.length; i++) {
    h += "<p class='wp-m' style='margin:" + (i > 0 ? "6px" : "0") + " 0 0 0;" + WP_F + "font-size:12px;color:" + (i === linhasRodape.length - 1 ? "#8A90A0" : "#6B7280") + ";mso-line-height-rule:exactly;line-height:18px;'>" + linhasRodape[i] + "</p>";
  }
  h += "</td></tr></table>";
  h += "<!--[if mso]></td></tr></table><![endif]-->";
  h += "</td></tr></table></body></html>";
  return h;
}

// Parágrafo livre (HTML já escapado pelo chamador)
function wpTexto(html) {
  return "<tr><td class='wp-pad' style='padding:8px 32px;'><p class='wp-m' style='margin:0;" + WP_F + "font-size:15px;color:#5B6170;mso-line-height-rule:exactly;line-height:23px;'>" + html + "</p></td></tr>";
}

// Título de seção com subtítulo
function wpSecao(titulo, sub) {
  return "<tr><td class='wp-pad' style='padding:24px 32px 12px 32px;'>" +
    "<p class='wp-t' style='margin:0;" + WP_F + "font-size:16px;font-weight:bold;color:#303030;mso-line-height-rule:exactly;line-height:22px;'>" + wpEsc(titulo) + "</p>" +
    (sub ? "<p class='wp-m' style='margin:4px 0 0 0;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:18px;'>" + sub + "</p>" : "") + "</td></tr>";
}

// Cartões de indicador lado a lado. lista: [{rotulo, valor, estilo, sub}], titulo (opcional) vira um rótulo pequeno acima.
// Sem estilo, o primeiro é "medio" (verde-oliva) e os outros "neutro", como no Guardião.
function wpKpis(lista, titulo) {
  const n = lista.length;
  const larg = (100 / n).toFixed(2);
  let h = "<tr><td class='wp-pad' style='padding:20px 32px 8px 32px;'>";
  if (titulo) h += "<p class='wp-m' style='margin:0 0 8px 0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;mso-line-height-rule:exactly;line-height:15px;'>" + wpEsc(titulo) + "</p>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  // Valor longo (ex.: R$ 99.716,16) com 3 ou mais cartões lado a lado: fonte menor para caber numa linha.
  const maiorValor = lista.reduce(function (m, k) { return Math.max(m, String(k.valor === undefined ? "" : k.valor).length); }, 0);
  const tam = n >= 3 && maiorValor > 9 ? 20 : n >= 2 && maiorValor > 14 ? 20 : 26;
  for (let i = 0; i < n; i++) {
    const k = lista[i];
    const nome = WP_ESTILOS[k.estilo] ? k.estilo : (i === 0 ? "medio" : "neutro");
    const e = nome === "forte" ? WP_ESTILOS.medio : WP_ESTILOS[nome];
    const cls = nome === "forte" ? "medio" : nome;
    const pad = n === 1 ? "" : (i === 0 ? "padding-right:6px;" : (i === n - 1 ? "padding-left:6px;" : "padding:0 3px;"));
    h += "<td class='wp-kpi' width='" + larg + "%' valign='top' style='width:" + larg + "%;" + pad + "'>" +
      "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border-radius:8px;padding:16px;'>" +
      "<p class='wp-c-" + cls + "' style='margin:0;" + WP_F + "font-size:" + tam + "px;font-weight:bold;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:" + (tam + 6) + "px;white-space:nowrap;'>" + wpEsc(k.valor) + "</p>" +
      "<p class='wp-c-" + cls + "' style='margin:4px 0 0 0;" + WP_F + "font-size:13px;color:" + (nome === "neutro" ? "#5B6170" : e.cor) + ";mso-line-height-rule:exactly;line-height:18px;'>" + wpEsc(k.rotulo) + "</p>" +
      (k.sub ? "<p class='wp-m' style='margin:2px 0 0 0;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(k.sub) + "</p>" : "") +
      "</td></tr></table></td>";
  }
  return h + "</tr></table></td></tr>";
}

// Tabela. colunas: [{t, a: "left"|"right"|"center", w, oculta}], linhas: [[html da célula, ...], ...]
// oculta = some em tela pequena. nota (opcional): texto abaixo da tabela.
function wpTabela(colunas, linhas, nota) {
  let h = "<tr><td class='wp-pad' style='padding:4px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' class='wp-bd' style='border:1px solid #E5E7EB;border-radius:8px;border-collapse:separate;'><tr>";
  for (let c = 0; c < colunas.length; c++) {
    const col = colunas[c];
    const canto = c === 0 ? "border-radius:8px 0 0 0;" : (c === colunas.length - 1 ? "border-radius:0 8px 0 0;" : "");
    h += "<td bgcolor='#F9FAFB' align='" + (col.a || "left") + "'" + (col.w ? " width='" + col.w + "'" : "") + " class='wp-soft wp-m" + (col.oculta ? " wp-hide" : "") + "'" +
      " style='background:#F9FAFB;padding:10px 12px;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;mso-line-height-rule:exactly;line-height:15px;" + canto + "'>" + wpEsc(col.t) + "</td>";
  }
  h += "</tr>";
  if (linhas.length === 0) {
    h += "<tr><td colspan='" + colunas.length + "' class='wp-bd wp-m' style='border-top:1px solid #F3F4F6;padding:14px 12px;" + WP_F + "font-size:13px;color:#6B7280;'>Nada para mostrar.</td></tr>";
  }
  for (let i = 0; i < linhas.length; i++) {
    h += "<tr>";
    for (let c = 0; c < colunas.length; c++) {
      const col = colunas[c];
      h += "<td" + (col.a ? " align='" + col.a + "'" : "") + " valign='middle' class='wp-bd wp-t" + (col.oculta ? " wp-hide" : "") + "'" +
        " style='border-top:1px solid #F3F4F6;padding:10px 12px;" + WP_F + "font-size:13px;color:#303030;mso-line-height-rule:exactly;line-height:18px;'>" + (linhas[i][c] === undefined ? "" : linhas[i][c]) + "</td>";
    }
    h += "</tr>";
  }
  h += "</table>" + (nota ? "<p class='wp-m' style='margin:8px 2px 0 2px;" + WP_F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:17px;'>" + nota + "</p>" : "") + "</td></tr>";
  return h;
}

// Pílula de destaque (para dentro de uma célula). a: "left" | "right". Texto curto (até 3 caracteres) vira círculo,
// como a posição do ranking do Guardião.
function wpBadge(texto, estilo, a) {
  const nome = WP_ESTILOS[estilo] ? estilo : "neutro";
  const e = nome === "neutro" ? { bg: "#F3F4F6", cor: "#5B6170" } : WP_ESTILOS[nome];
  const t = String(texto === null || texto === undefined ? "" : texto);
  const alinhar = a === "right" ? " align='right'" : "";
  if (t.length <= 3) {
    return "<table role='presentation' cellpadding='0' cellspacing='0' border='0'" + alinhar + "><tr><td width='24' height='24' align='center' valign='middle' bgcolor='" + e.bg + "' style='width:24px;height:24px;background:" + e.bg + ";border-radius:12px;" + WP_F + "font-size:12px;font-weight:bold;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:24px;'>" + wpEsc(t) + "</td></tr></table>";
  }
  return "<table role='presentation' cellpadding='0' cellspacing='0' border='0'" + alinhar + "><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border-radius:20px;padding:3px 10px;" + WP_F + "font-size:11px;font-weight:bold;color:" + e.cor + ";white-space:nowrap;mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(t) + "</td></tr></table>";
}

// Barra proporcional (para dentro de uma célula). pct 0-100; forte = verde-oliva cheio, senão oliva claro
function wpBarra(pct, forte) {
  const w = Math.max(4, Math.min(100, Math.round(pct)));
  const cor = forte ? "#5A6344" : "#BFC4AC";
  return "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='margin-top:6px;'><tr>" +
    "<td width='" + w + "%' height='6' bgcolor='" + cor + "' style='height:6px;background:" + cor + ";border-radius:3px;font-size:0;line-height:0;'>&nbsp;</td>" +
    (w < 100 ? "<td width='" + (100 - w) + "%' height='6' style='height:6px;font-size:0;line-height:0;'>&nbsp;</td>" : "") + "</tr></table>";
}

// Botão quadrado com seta (para dentro de uma célula): abre a planilha ou lista da linha
function wpSeta(url, titulo) {
  return "<table role='presentation' cellpadding='0' cellspacing='0' border='0' align='right'><tr><td width='32' height='32' align='center' valign='middle' bgcolor='#303030' style='width:32px;height:32px;background:#303030;border-radius:8px;'>" +
    "<a href='" + wpEsc(url) + "' target='_blank' title='" + wpEsc(titulo) + "' aria-label='" + wpEsc(titulo) + "' style='display:block;width:32px;" + WP_F + "font-size:18px;font-weight:bold;color:#FFFFFF;text-decoration:none;mso-line-height-rule:exactly;line-height:32px;border-radius:8px;'>&rarr;</a></td></tr></table>";
}

// Botão de chamada (linha própria)
function wpBotao(url, rotulo) {
  return "<tr><td class='wp-pad' align='left' style='padding:16px 32px 8px 32px;'><table role='presentation' cellpadding='0' cellspacing='0' border='0'><tr><td align='center' bgcolor='#303030' style='background:#303030;border-radius:8px;'>" +
    "<a href='" + wpEsc(url) + "' target='_blank' style='display:block;padding:12px 24px;" + WP_F + "font-size:14px;font-weight:bold;color:#FFFFFF;text-decoration:none;mso-line-height-rule:exactly;line-height:20px;border-radius:8px;'>" + wpEsc(rotulo) + "</a></td></tr></table></td></tr>";
}

// Caixa de aviso (linha própria): titulo + corpo em HTML
function wpAviso(titulo, corpoHtml, estilo) {
  const nome = WP_ESTILOS[estilo] ? estilo : "medio";
  const e = nome === "forte" ? WP_ESTILOS.medio : WP_ESTILOS[nome];
  const cls = nome === "forte" ? "medio" : nome;
  return "<tr><td class='wp-pad' style='padding:16px 32px 8px 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='" + e.bg + "' style='background:" + e.bg + ";border:1px solid " + e.borda + ";border-radius:8px;padding:16px 18px;'>" +
    "<p class='wp-c-" + cls + "' style='margin:0;" + WP_F + "font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:" + e.cor + ";mso-line-height-rule:exactly;line-height:16px;'>" + wpEsc(titulo) + "</p>" +
    "<p class='wp-t' style='margin:8px 0 0 0;" + WP_F + "font-size:13px;color:#303030;mso-line-height-rule:exactly;line-height:20px;'>" + corpoHtml + "</p></td></tr></table></td></tr>";
}
